using Avalonia;
using Avalonia.Controls;
using Avalonia.Layout;
namespace WirePulse;

public sealed class StartupPrompt : Window
{
    public StartupPrompt(Func<bool, string?> choose) : this((enabled, _) => choose(enabled)) {}
    public StartupPrompt(Func<bool, bool, string?> choose) { Title = L10n.Text("Inicio automático · WirePulse"); Icon = new WindowIcon(Path.Combine(AppContext.BaseDirectory, "Assets", "WirePulse.png")); Width = 460; MinHeight=220;MaxHeight=500;SizeToContent=SizeToContent.Height; CanResize = false; WindowStartupLocation = WindowStartupLocation.CenterScreen; var content = new StackPanel { Spacing = 18, Margin = new Thickness(24) }; content.Children.Add(new TextBlock { Text = L10n.Text("¿Abrir WirePulse al iniciar sesión?"), FontSize = 19, FontWeight = Avalonia.Media.FontWeight.SemiBold, TextWrapping = Avalonia.Media.TextWrapping.Wrap }); content.Children.Add(new TextBlock { Text = L10n.Text("El fondo se abrirá sin mostrar los ajustes. Puedes cambiar esta opción más adelante en Ajustes → Inicio."), TextWrapping = Avalonia.Media.TextWrapping.Wrap }); var priority = new CheckBox { Content = L10n.Text("Inicio prioritario (Windows)"), IsVisible = OperatingSystem.IsWindows() }; content.Children.Add(priority); if (OperatingSystem.IsWindows()) content.Children.Add(new TextBlock { Text = L10n.Text("Iniciar al entrar en tu sesión, sin retraso configurado. Windows decide el orden final de arranque."), TextWrapping = Avalonia.Media.TextWrapping.Wrap }); var buttons = new StackPanel { Orientation = Orientation.Horizontal, Spacing = 10, HorizontalAlignment = HorizontalAlignment.Right }; var error = new TextBlock { TextWrapping = Avalonia.Media.TextWrapping.Wrap, Foreground = Avalonia.Media.Brushes.OrangeRed }; content.Children.Add(error); void Apply(bool value) { var message = choose(value, value && priority.IsChecked == true); if (message == null) Close(); else error.Text = L10n.Text(message); } var no = new Button { Content = L10n.Text("Ahora no") }; var yes = new Button { Content = L10n.Text("Sí, abrir al iniciar") }; no.Click += (_, _) => { Apply(false); }; yes.Click += (_, _) => { Apply(true); }; buttons.Children.Add(no); buttons.Children.Add(yes); content.Children.Add(buttons); Content = content; }
}
